sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

    var URL_TYPE_CATEGORY_SYSID = 'cc8d30c3d70322007a6de294de610322';

    // Always upsert the observable — every alert becomes one, regardless
    // of whether it goes on to become an indicator.
    var entity = source.entity ? source.entity.toString() : '';
    if (entity) {
        var obs = new GlideRecord('sn_ti_observable');
		obs.addQuery('value', entity);
		obs.query();
		if (!obs.next()) {
			obs.initialize();
			obs.setValue('type_category', URL_TYPE_CATEGORY_SYSID);
			obs.setValue('value', entity);
			obs.setValue('finding', 'Suspicious');
			obs.setValue('x_doppe_doppel_t_0_doppel_owned', true);
			if (!obs.insert()) {
				log.error('Failed to insert observable for entity: ' + entity);
			}
		}
    }

    // Only create an indicator when ALL of the following match:
    //   severity == "high"
    //   entity_state == "suspicious"
    //   queue_state == "monitoring" OR "needs_confirmation"
    var severity = source.severity ? source.severity.toString() : '';
    var entityState = source.entity_state ? source.entity_state.toString() : '';
    var queueState = source.queue_state ? source.queue_state.toString() : '';

    var qualifies =
        (severity === 'high') &&
        (entityState === 'suspicious') &&
        (queueState === 'monitoring' || queueState === 'needs_confirmation');

    if (!qualifies) {
        log.info('Skipping indicator for ' + source.alert_id +
                  ' — severity=' + severity +
                  ', entity_state=' + entityState +
                  ', queue_state=' + queueState +
                  ' (needs severity=high AND entity_state=suspicious AND queue_state=monitoring/needs_confirmation)');
        ignore = true;
    }

})(source, map, log, target);
